using Microsoft.AspNetCore.Identity;
using ShipmentTracker.Models;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider serviceProvider)
    {
        using var scope = serviceProvider.CreateScope();
        var context = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();

        await context.Database.EnsureCreatedAsync();

        // Create roles
        string[] roles = ["Dispatcher", "Customer"];
        foreach (var role in roles)
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }

        // Create dispatcher user
        if (await userManager.FindByEmailAsync("dispatcher@shiptrack.com") is null)
        {
            var dispatcher = new ApplicationUser
            {
                UserName = "dispatcher@shiptrack.com",
                Email = "dispatcher@shiptrack.com",
                EmailConfirmed = true,
                Role = "Dispatcher"
            };
            await userManager.CreateAsync(dispatcher, "Dispatch1!");
            await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
        }

        // Create customer user
        if (await userManager.FindByEmailAsync("customer@example.com") is null)
        {
            var customer = new ApplicationUser
            {
                UserName = "customer@example.com",
                Email = "customer@example.com",
                EmailConfirmed = true,
                Role = "Customer"
            };
            await userManager.CreateAsync(customer, "Customer1!");
            await userManager.AddToRoleAsync(customer, "Customer");
        }

        // Seed shipments
        if (!context.Shipments.Any())
        {
            context.Shipments.AddRange(
                new Shipment
                {
                    TrackingNumber = "ST-100001",
                    Origin = "New York, USA",
                    Destination = "London, UK",
                    Status = ShipmentStatus.InTransit,
                    CreatedAt = DateTime.UtcNow.AddDays(-3),
                    EstimatedDelivery = DateTime.UtcNow.AddDays(4),
                    CustomerEmail = "customer@example.com",
                    Description = "Electronics - Laptop"
                },
                new Shipment
                {
                    TrackingNumber = "ST-100002",
                    Origin = "Tokyo, Japan",
                    Destination = "Sydney, Australia",
                    Status = ShipmentStatus.PickedUp,
                    CreatedAt = DateTime.UtcNow.AddDays(-1),
                    EstimatedDelivery = DateTime.UtcNow.AddDays(6),
                    CustomerEmail = "customer@example.com",
                    Description = "Furniture - Office Chair"
                },
                new Shipment
                {
                    TrackingNumber = "ST-100003",
                    Origin = "Berlin, Germany",
                    Destination = "Paris, France",
                    Status = ShipmentStatus.Delivered,
                    CreatedAt = DateTime.UtcNow.AddDays(-7),
                    EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                    CustomerEmail = "another@example.com",
                    Description = "Documents - Legal Papers"
                },
                new Shipment
                {
                    TrackingNumber = "ST-100004",
                    Origin = "Shanghai, China",
                    Destination = "Los Angeles, USA",
                    Status = ShipmentStatus.Pending,
                    CreatedAt = DateTime.UtcNow,
                    EstimatedDelivery = DateTime.UtcNow.AddDays(10),
                    CustomerEmail = "customer@example.com",
                    Description = "Clothing - Winter Collection"
                }
            );
            await context.SaveChangesAsync();
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Models;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // GET all shipments (dispatchers see all, customers see their own)
        group.MapGet("/", async (ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext http) =>
        {
            var user = await userManager.GetUserAsync(http.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");

            var query = isDispatcher
                ? db.Shipments.AsQueryable()
                : db.Shipments.Where(s => s.CustomerEmail == user.Email);

            var shipments = await query.OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Description = s.Description
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // GET single shipment by tracking number (public lookup)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Where(s => s.TrackingNumber == trackingNumber)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Description = s.Description
                })
                .FirstOrDefaultAsync();

            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        // POST create shipment (dispatchers only)
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (CreateShipmentRequest request, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = $"ST-{DateTime.UtcNow.Ticks % 1000000:D6}",
                Origin = request.Origin,
                Destination = request.Destination,
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow,
                EstimatedDelivery = request.EstimatedDelivery,
                CustomerEmail = request.CustomerEmail,
                Description = request.Description
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            return Results.Created($"/api/shipments/track/{shipment.TrackingNumber}", new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery,
                CustomerEmail = shipment.CustomerEmail,
                Description = shipment.Description
            });
        });

        // PUT update shipment status (dispatchers only)
        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = request.Status;
            if (request.EstimatedDelivery.HasValue)
                shipment.EstimatedDelivery = request.EstimatedDelivery;

            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }
}

