@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService

<PageTitle>Shipments</PageTitle>

<h1>Shipments</h1>

<AuthorizeView Roles="Dispatcher">
    <Authorized>
        <button class="btn btn-success mb-3" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </Authorized>
</AuthorizeView>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" placeholder="City, Country" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" placeholder="City, Country" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Customer Email</label>
                    <input class="form-control" type="email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Estimated Delivery</label>
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <input class="form-control" @bind="newShipment.Description" placeholder="Package contents" />
                </div>
                <div class="col-12">
                    <button class="btn btn-primary me-2" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-secondary">No shipments found.</div>
}
else
{
    <div class="mb-3">
        <input class="form-control" placeholder="Filter by tracking #, destination, or status..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Description</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Description</td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>
                            <AuthorizeView Roles="Dispatcher">
                                <Authorized>
                                    <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(shipment)">
                                        Update
                                    </button>
                                </Authorized>
                            </AuthorizeView>
                        </td>
                    </tr>
                    @if (editingId == shipment.Id)
                    {
                        <tr>
                            <td colspan="7">
                                <div class="d-flex align-items-center gap-3 p-2 bg-light">
                                    <select class="form-select w-auto" @bind="editStatus">
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@status">@status</option>
                                        }
                                    </select>
                                    <input type="date" class="form-control w-auto" @bind="editEstDelivery" />
                                    <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(shipment.Id)">Save</button>
                                    <button class="btn btn-sm btn-secondary" @onclick="() => editingId = null">Cancel</button>
                                </div>
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string filterText = "";
    private bool showCreateForm;
    private CreateShipmentRequest newShipment = new();
    private int? editingId;
    private ShipmentStatus editStatus;
    private DateTime? editEstDelivery;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments
            : shipments.Where(s =>
                s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Status.ToString().Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
        loading = false;
    }

    private void ShowCreateForm()
    {
        newShipment = new CreateShipmentRequest { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        var result = await ShipmentService.CreateShipmentAsync(newShipment);
        if (result is not null)
        {
            shipments.Insert(0, result);
            showCreateForm = false;
        }
    }

    private void StartEdit(ShipmentDto shipment)
    {
        editingId = shipment.Id;
        editStatus = shipment.Status;
        editEstDelivery = shipment.EstimatedDelivery;
    }

    private async Task SaveStatus(int id)
    {
        var success = await ShipmentService.UpdateStatusAsync(id, new UpdateShipmentStatusRequest
        {
            Status = editStatus,
            EstimatedDelivery = editEstDelivery
        });

        if (success)
        {
            var shipment = shipments.First(s => s.Id == id);
            shipment.Status = editStatus;
            shipment.EstimatedDelivery = editEstDelivery;
            editingId = null;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

